#!/usr/bin/env node
// Castaway header 17: the theme tune, playing in a DOS text-mode module player.
//
// Style: a mid-90s text-mode module player (status lines of label: value pairs, channel lines,
// a character-cell spectrum analyser in two stereo bands, a scrolling pattern view under a grey
// current-row band). The look follows the catalogue entry trk-08 (the Open Cubic Player screen);
// nothing of that program is reproduced: the player here, "driftwood player" by "Neap Tide
// Software", is invented, and so is every word on its title bar.
//
// What is real. Everything the screen plays is the project's own theme,
// media/audio/music/castaway_lofi_theme_loop_60s.wav, which tools/make_audio.py synthesizes:
//   * the pattern view is that script's score, transcribed at 16 rows a bar (one row per
//     sixteenth note, 0.1875 s): its chords (Gm9 C13 Fmaj9 Dm9, rootless voicings), its kalimba
//     melody note for note, its bass line with the chromatic lead-ins, and its drums. The swing
//     ("offbeats land late" by 0.07, 0.03 and 0.08 of a beat) becomes tracker note delays: at
//     speed 6 and 80 bpm one tick is 31.25 ms, so SD2, SD1 and SD2;
//   * tempo 6 / bpm 80 / 16 rows / 20 orders / 0:00-0:59 are the loop's real clock;
//   * the spectrum analyser, the eight-band CASTAWAY wordmark and the peak power meter are the
//     WAV's actual spectrum and level, measured row by row (see --analyse below) and embedded
//     here as data, so the generator needs nothing but itself.
// The display loop is the song loop: 60 s, 320 rows. It starts at bar 11 (the theme section)
// so the first frame is a busy one. Beside the title, a small pixel scene of the video plays a
// classic: she sips a coconut while a ship crosses the horizon behind her, unseen.
//
// Regenerate:            node examples/castaway/src/17-module-player_opus_5.5.mjs
// Re-measure the WAV:    node .../17-module-player_opus_5.5.mjs --analyse=<path to the wav>
//                        (rewrites the DATA block of this file in place; reads the WAV only)
// Inspect one frame:     node .../17-module-player_opus_5.5.mjs --freeze=<f> --out=<file.svg>
//                        (f = display row 0-319; 0 is bar 11, 96 the coconut, 112 the ship, 160 bar 1)
//
// Plain Node, no dependencies, deterministic (no clock; a seeded PRNG for the vinyl meter).
// Text is an 8x14 bitmap font emitted as <path>/<use>, never <text>. Steady clockwork (scroll,
// counters, the little scene) is CSS; the data-heavy parts (analyser bars, meters, channel
// readouts) are SMIL value lists, which are far smaller. CSS cannot pause SMIL, so every SMIL
// part has a still twin that prefers-reduced-motion swaps in.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const SELF = fileURLToPath(import.meta.url);
const HERE = path.dirname(SELF);
const SLUG = '17-module-player_opus_5.5';
const argv = process.argv.slice(2);
const arg = (n) => { const a = argv.find((x) => x.startsWith(`--${n}=`)); return a ? a.slice(n.length + 3) : null; };
const FREEZE = arg('freeze') !== null ? Number(arg('freeze')) : null;
const OUT = arg('out') || path.join(HERE, '..', 'assets', `${SLUG}.svg`);

// ---------------------------------------------------------------------------------------------
// The song clock
// ---------------------------------------------------------------------------------------------
const T = 60;            // seconds: one pass of the theme, which loops seamlessly
const NF = 320;          // rows in the song: 20 bars x 16
const ROW_S = T / NF;    // 0.1875 s
const OFFSET = 160;      // the display starts at song row 160 = bar 11, row 00
const F0 = FREEZE ?? 0;  // the display frame the static parts show
const songRow = (f) => (((f + OFFSET) % NF) + NF) % NF;
const disp = (arr) => Array.from({ length: NF }, (_, f) => arr[songRow(f)]);

// ---------------------------------------------------------------------------------------------
// The score, transcribed from tools/make_audio.py (CHORDS, PROGRESSION, MELODY, render_pass)
// ---------------------------------------------------------------------------------------------
const CHORDS = { // bass root, rootless electric-piano voicing (MIDI)
  Gm9: [43, [58, 62, 65, 69]],
  C13: [36, [58, 62, 64, 69]],
  Fmaj9: [41, [57, 60, 64, 67]],
  Dm9: [38, [53, 57, 60, 64]],
};
const PROGRESSION = ['Gm9', 'C13', 'Fmaj9', 'Dm9']; // ii-V-I-vi in F, one chord a bar
const CHORD_SYM = { Gm9: 'Gm9', C13: 'C13', Fmaj9: 'FM9', Dm9: 'Dm9' };
const SECTIONS = [['intro', 1], ['groove', 3], ['theme', 11], ['break', 17]];
const MELODY = [ // (bar, beat, MIDI) for the kalimba
  [7, 0.5, 81], [7, 1.0, 84], [7, 1.5, 81], [7, 2.5, 79],
  [8, 1.0, 77], [8, 1.5, 79], [8, 2.0, 81],
  [9, 0.5, 86], [9, 1.0, 84], [9, 1.75, 81], [9, 2.5, 79],
  [10, 1.0, 81], [10, 2.0, 79], [10, 3.0, 76],
  [11, 0.0, 77], [11, 0.5, 81], [11, 1.0, 84], [11, 1.5, 88], [11, 2.0, 86], [11, 3.0, 84],
  [12, 0.5, 81], [12, 1.0, 84], [12, 1.75, 86], [12, 2.5, 89], [12, 3.0, 88], [12, 3.5, 86],
  [13, 0.0, 86], [13, 1.5, 84], [13, 2.0, 81], [13, 2.5, 82], [13, 3.0, 81], [13, 3.5, 79],
  [14, 0.0, 79], [14, 1.5, 81], [14, 2.0, 84], [14, 2.5, 86], [14, 3.0, 88],
  [15, 0.0, 89], [15, 2.0, 88], [15, 2.5, 84], [15, 3.0, 81],
  [16, 0.5, 79], [16, 1.0, 81], [16, 1.5, 84], [16, 3.5, 86],
  [17, 0.0, 86], [17, 2.0, 84],
  [18, 0.0, 81], [18, 2.0, 79],
  [19, 1.0, 84], [19, 2.5, 81],
  [20, 0.0, 84], [20, 0.5, 88], [20, 1.0, 91], [20, 2.0, 89],
];
const chordAt = (bar) => PROGRESSION[(bar - 1) % 4];
const SD = [0, 2, 1, 2]; // note delay in ticks for each sixteenth of a beat (the swing)
const NOTE = ['C-', 'C#', 'D-', 'D#', 'E-', 'F-', 'F#', 'G-', 'G#', 'A-', 'A#', 'B-'];
const noteName = (m) => NOTE[m % 12] + (Math.floor(m / 12) - 1);
const hx = (n, w = 2) => n.toString(16).toUpperCase().padStart(w, '0');
const vol = (v) => hx(Math.round(v * 64));
const rowOf = (bar, beat) => (bar - 1) * 16 + Math.round(beat * 4);
const sdOf = (beat) => SD[Math.round(beat * 4) % 4];

// Channels. ins numbers are the synth voices in the order the script defines them.
const CH = [
  { n: 1, name: 'keys', ins: 1 },
  { n: 2, name: 'kalimba', ins: 2 },
  { n: 3, name: 'bass', ins: 3 },
  { n: 4, name: 'drums', ins: 4 },
  { n: 5, name: 'hats', ins: 7 },
  { n: 6, name: 'pad', ins: 9 },
  { n: 7, name: 'vinyl', ins: 10 },
  { n: 8, name: 'riser', ins: 11 },
];
const EV = CH.map(() => []); // per channel: { row, note, ins, v, sd, word, env }
for (let bar = 1; bar <= 20; bar++) {
  const ch = chordAt(bar), voicing = CHORDS[ch][1];
  // electric piano: two strums a bar
  for (const [b, v, hold] of [[0, 0.8, 2.4], [2.5, 0.5, 1.4]]) {
    EV[0].push({ row: rowOf(bar, b), note: noteName(voicing[0]), ins: 1, v, sd: sdOf(b), word: b ? 'swing' : 'strum', env: { k: 'hold', hold: hold * 0.75, decay: 0.9 } });
  }
  if (bar >= 3) {
    // bass
    const root = CHORDS[ch][0];
    const notes = bar >= 17
      ? [[0, 3.6, root, 0.75, 'root']]
      : [[0, 2.2, root, 0.9, 'root'], [2.5, 0.8, root + 7, 0.55, 'fifth'], [3.5, 0.4, CHORDS[chordAt(bar + 1)][0] - 1, 0.6, 'lead-in']];
    for (const [b, hold, m, v, word] of notes) {
      EV[2].push({ row: rowOf(bar, b), note: noteName(m), ins: 3, v, sd: sdOf(b), word, env: { k: 'hold', hold: hold * 0.75, decay: 0.6 } });
      const off = Math.round((b + hold) * 4);
      if (off < 16 && !notes.some(([b2]) => Math.round(b2 * 4) === off)) EV[2].push({ row: (bar - 1) * 16 + off, note: '===', ins: 3, v: 0, sd: 0, word: 'off', env: { k: 'off' } });
    }
    // drums (kick C-2, rim C#2, snare D-2: the General MIDI drum keys) and hats
    const drum = (b, kind, v) => {
      const [note, ins, decay] = { kick: ['C-2', 4, 7], snare: ['D-2', 5, 14], rim: ['C#2', 6, 30], hat: ['F#2', 7, 40], ohat: ['A#2', 8, 9] }[kind];
      const word = kind === 'ohat' ? 'open' : (v < 0.25 && kind === 'snare') ? 'ghost' : sdOf(b) ? 'swing' : kind === 'rim' ? 'rim' : '------';
      (kind === 'hat' || kind === 'ohat' ? EV[4] : EV[3]).push({ row: rowOf(bar, b), note, ins, v, sd: sdOf(b), word, env: { k: 'exp', decay } });
    };
    if (bar >= 17) {
      drum(0, 'kick', 0.75); drum(1, 'rim', 0.45); drum(3, 'rim', 0.45);
    } else {
      const fill = bar % 4 === 2;
      for (const b of fill ? [0, 1.75, 2.5] : [0, 2.5]) drum(b, 'kick', b === 0 ? 0.95 : 0.8);
      drum(1, 'snare', 0.75); drum(3, 'snare', 0.75);
      if (fill) drum(3.75, 'snare', 0.22);
      for (let b = 0; b < 4; b += bar >= 11 ? 0.25 : 0.5) {
        if (fill && b === 3.5) { drum(b, 'ohat', 0.3); continue; }
        drum(b, 'hat', b % 1 === 0 ? 0.5 : b % 0.5 === 0 ? 0.32 : 0.16);
      }
    }
  }
  // breakdown pad, which fades in from 0.6 s before each of bars 17-20
  if (bar >= 17) EV[5].push({ row: (bar - 1) * 16 - 3, note: noteName(voicing[0]), ins: 9, v: 0.35, sd: 0, word: 'swell', env: { k: 'pad' } });
}
for (const [bar, b, m] of MELODY) {
  const v = (b % 1 === 0 ? 0.75 : 0.6) * (bar === 20 ? 0.7 : 1);
  EV[1].push({ row: rowOf(bar, b), note: noteName(m), ins: 2, v, sd: sdOf(b), word: sdOf(b) ? 'swing' : 'tine', env: { k: 'exp', decay: 2.2 } });
}
EV[6].push({ row: 0, note: 'C-5', ins: 10, v: 0.12, sd: 0, word: 'crackle', env: { k: 'vinyl' } });
EV[7].push({ row: 23, note: 'C-5', ins: 11, v: 0.25, sd: 0, word: 'riser', env: { k: 'riser' } }); // noise swell, 4.4 s to 6.0 s
EV[7].push({ row: 32, note: '---', ins: 0, v: 0, sd: 0, word: '------', env: { k: 'off' } });
EV.forEach((list) => list.sort((a, b) => a.row - b.row));

// What each channel line shows on each song row: the latest event (the loop wraps).
function lastEvent(list, row) {
  let e = null;
  for (const x of list) if (x.row <= row) e = x;
  return e || list[list.length - 1];
}
const IDLE = '-- --- -- -------';
function chanText(ci, row) {
  const e = lastEvent(EV[ci], row);
  if (!e || e.env.k === 'off' && e.ins === 0) return IDLE;
  if (ci === 5 && !(row >= 16 * 16 - 3)) return IDLE; // the pad only plays in the breakdown
  const v = e.env.k === 'off' ? '00' : vol(e.v);
  return `${hx(e.ins)} ${e.note} ${v} ${e.word.padEnd(7)}`;
}

// Channel meters from the score: level 0..1 per song row.
let seed = 1992;
const rnd = () => { seed = (seed * 1103515245 + 12345) >>> 0; return seed / 2 ** 32; };
function envAt(e, t) {
  if (t < 0) return 0;
  switch (e.env.k) {
    case 'hold': return t < e.env.hold ? e.v * Math.exp(-t * e.env.decay) : e.v * Math.exp(-e.env.hold * e.env.decay) * Math.exp(-(t - e.env.hold) / 0.08);
    case 'exp': return e.v * Math.exp(-t * e.env.decay);
    case 'pad': { const dur = 3 + 1.2; return t > dur ? 0 : 0.8 * Math.min(1, t / 1.5) * Math.min(1, Math.max(0, (dur - t) / 1.2)); }
    case 'riser': return t > 1.6 ? 0 : 0.9 * (t / 1.6) ** 3;
    default: return 0;
  }
}
const METER = CH.map((c, ci) => {
  const out = [];
  for (let r = 0; r < NF; r++) {
    if (ci === 6) { const x = rnd(); out.push(0.12 + 0.12 * x + (x > 0.93 ? 0.35 : 0)); continue; }
    let lv = 0;
    for (const e of EV[ci]) {
      for (const shift of [0, NF]) { // the previous pass rings into this one
        const t = (r + shift - e.row) * ROW_S + 0.04 - e.sd * 0.03125;
        if (t >= 0 && t < 8) lv = Math.max(lv, envAt(e, t));
      }
    }
    out.push(Math.min(1, lv * 1.25));
  }
  return out;
});

// ---------------------------------------------------------------------------------------------
// --analyse: measure the theme WAV row by row and write the numbers into the DATA block below
// ---------------------------------------------------------------------------------------------
function analyse(wavPath) {
  const buf = fs.readFileSync(wavPath);
  let p = 12, fmt, data;
  while (p + 8 <= buf.length) {
    const id = buf.toString('ascii', p, p + 4), sz = buf.readUInt32LE(p + 4);
    if (id === 'fmt ') fmt = { ch: buf.readUInt16LE(p + 10), sr: buf.readUInt32LE(p + 12), bits: buf.readUInt16LE(p + 22) };
    if (id === 'data') data = buf.subarray(p + 8, p + 8 + sz);
    p += 8 + sz + (sz & 1);
  }
  if (!fmt || fmt.ch !== 2 || fmt.bits !== 16) throw new Error('expected 16-bit stereo PCM');
  const SR = fmt.sr, N = data.length / 4;
  const L = new Float64Array(N), R = new Float64Array(N);
  for (let i = 0; i < N; i++) { L[i] = data.readInt16LE(i * 4) / 32768; R[i] = data.readInt16LE(i * 4 + 2) / 32768; }
  const W = 2048, SUB = 4, NS = NF * SUB;
  const hann = Float64Array.from({ length: W }, (_, i) => 0.5 - 0.5 * Math.cos((2 * Math.PI * i) / W));
  const wsum = hann.reduce((a, b) => a + b, 0);
  function fft(re, im) {
    const n = re.length;
    for (let i = 1, j = 0; i < n; i++) {
      let bit = n >> 1;
      for (; j & bit; bit >>= 1) j ^= bit;
      j ^= bit;
      if (i < j) { [re[i], re[j]] = [re[j], re[i]]; [im[i], im[j]] = [im[j], im[i]]; }
    }
    for (let len = 2; len <= n; len <<= 1) {
      const ang = (-2 * Math.PI) / len, wr = Math.cos(ang), wi = Math.sin(ang);
      for (let i = 0; i < n; i += len) {
        let cr = 1, ci = 0;
        for (let j = 0; j < len / 2; j++) {
          const a = i + j, b = a + len / 2;
          const xr = re[b] * cr - im[b] * ci, xi = re[b] * ci + im[b] * cr;
          re[b] = re[a] - xr; im[b] = im[a] - xi; re[a] += xr; im[a] += xi;
          const t = cr * wr - ci * wi; ci = cr * wi + ci * wr; cr = t;
        }
      }
    }
  }
  const mag = (x, c) => {
    const re = new Float64Array(W), im = new Float64Array(W);
    let ss = 0;
    for (let i = 0; i < W; i++) { const s = x[(((c - W / 2 + i) % N) + N) % N]; ss += s * s; re[i] = s * hann[i]; }
    fft(re, im);
    const m = new Float64Array(W / 2);
    for (let k = 0; k < W / 2; k++) m[k] = (Math.hypot(re[k], im[k]) * 2) / wsum;
    return { m, rms: Math.sqrt(ss / W) };
  };
  const db = (a) => 20 * Math.log10(Math.max(a, 1e-9));
  const HZ = SR / W; // 23.4 Hz per FFT bin; two per analyser bar = 46.875 Hz
  const EDGES = [30, 90, 180, 360, 720, 1440, 2880, 5760, 12000];
  const raw = { L: [], R: [], word: [], peak: [[], []] };
  for (let s = 0; s < NS; s++) {
    const c = Math.round((s / SUB) * ROW_S * SR + 0.03 * SR);
    const a = mag(L, c), b = mag(R, c);
    for (const [key, sp] of [['L', a.m], ['R', b.m]]) raw[key].push(Array.from({ length: 64 }, (_, k) => db(Math.max(sp[2 * k + 2], sp[2 * k + 3]))));
    raw.word.push(EDGES.slice(0, 8).map((lo, i) => {
      let e = 0;
      for (let k = Math.ceil(lo / HZ); k < EDGES[i + 1] / HZ; k++) e += a.m[k] ** 2 + b.m[k] ** 2;
      return 10 * Math.log10(e + 1e-12);
    }));
    raw.peak[0].push(db(a.rms)); raw.peak[1].push(db(b.rms));
  }
  // analyser ballistics: instant rise, a steady fall; then one value per row (the max of the
  // four sub-frames around it), quantized.
  const perRow = (series, fall, map) => {
    const lv = new Float64Array(NS);
    let prev = 0;
    for (let pass = 0; pass < 2; pass++) for (let s = 0; s < NS; s++) { prev = Math.max(map(series[s]), prev - fall); lv[s] = prev; }
    return Array.from({ length: NF }, (_, r) => Math.max(...[-1, 0, 1, 2].map((d) => lv[(r * SUB + d + NS) % NS])));
  };
  const enc = (arr, max) => arr.map((v) => Math.round(Math.min(max, Math.max(0, v))).toString(36)).join('');
  // bars: -70 dB to -10 dB on a square law, so the loud low end towers and the quiet top end
  // sits near the baseline, as on the real thing
  const bars = (key) => Array.from({ length: 64 }, (_, k) => enc(perRow(raw[key].map((f) => f[k]), 1, (d) => 9 * Math.max(0, Math.min(1, (d + 70) / 60)) ** 2), 9));
  const pct = (arr, q) => { const s = [...arr].sort((x, y) => x - y); return s[Math.floor(q * (s.length - 1))]; };
  const word = Array.from({ length: 8 }, (_, i) => {
    const col = raw.word.map((f) => f[i]);
    const lo = pct(col, 0.08), hi = pct(col, 0.995);
    return enc(perRow(col, 0.9, (d) => ((d - lo) / (hi - lo)) * 14), 14);
  });
  const peak = raw.peak.map((col) => enc(perRow(col, 0.6, (d) => ((d + 34) / 26) * 20), 20));
  const out = { L: bars('L'), R: bars('R'), word, peak };
  const src = fs.readFileSync(SELF, 'utf8');
  // The markers are the last two lines in the file that consist of exactly these words.
  const a0 = src.lastIndexOf('\n// <' + 'data>\n') + 1, a1 = src.lastIndexOf('\n// </' + 'data>\n') + 1;
  const block = `// <data>\n// Measured by --analyse from ${path.basename(wavPath)}: ${N} samples at ${SR} Hz.\n`
    + `// L/R: 64 analyser bars per stereo side, one base-36 digit per row (0-9).\n`
    + `// word: 8 log-spaced bands (30 Hz to 12 kHz) for the letters (0-e). peak: L/R level (0-k).\n`
    + `const DATA = {\n${Object.entries(out).map(([k, v]) => `  ${k}: [\n${v.map((s) => `    '${s}',`).join('\n')}\n  ],`).join('\n')}\n};\n`;
  fs.writeFileSync(SELF, src.slice(0, a0) + block + src.slice(a1));
  console.log(`wrote DATA into ${SELF}`);
}
if (arg('analyse')) { analyse(arg('analyse')); process.exit(0); }

