// Bitmap -> compact path (greedy merge of horizontal runs into rectangles).
function bitmapPath(rows, width, sx = 1, sy = 1, ox = 0, oy = 0) {
  const rects = [];
  let open = [];
  for (let y = 0; y < rows.length; y++) {
    const runs = [];
    for (let x = 0; x < width;) {
      if (rows[y](x)) { const s0 = x; while (x < width && rows[y](x)) x++; runs.push([s0, x - s0]); } else x++;
    }
    const next = [];
    for (const [x0, w] of runs) {
      const o = open.find((r) => r.x === x0 && r.w === w && r.y + r.h === y);
      if (o) { o.h++; next.push(o); } else { const r = { x: x0, w, y, h: 1 }; rects.push(r); next.push(r); }
    }
    open = next;
  }
  const n = (v) => +v.toFixed(2);
  return rects.map((r) => `M${n(ox + r.x * sx)} ${n(oy + r.y * sy)}h${n(r.w * sx)}v${n(r.h * sy)}h${n(-r.w * sx)}z`).join('');
}
const glyphIds = new Map();
function gid(ch) {
  if (!FONT.has(ch)) throw new Error(`no glyph for ${JSON.stringify(ch)}`);
  if (!glyphIds.has(ch)) glyphIds.set(ch, `g${glyphIds.size.toString(36)}`);
  return glyphIds.get(ch);
}
const len = (s) => [...s].length;

// ---------------------------------------------------------------------------------------------
// Drawing helpers, addressed in character cells. Colour comes from the enclosing group's class.
// ---------------------------------------------------------------------------------------------
const PAL = {
  k: '#000000',  // black
  tb: '#00A8A8', // title bar teal
  w: '#E1E1E1',  // values
  lb: '#5E7BFF', // labels: the player's blue, lifted so it reads at README size
  dg: '#545454', // grey: rules, dots, separators, the current-row band
  gn: '#00A844', // analyser green
  cy: '#00A8FC', // analyser cyan
  bu: '#1428FF', // analyser blue tips
  mb: '#3552FF', // meter blocks
  nt: '#19C25B', // pattern notes (the analyser green, a touch brighter for small text)
  ug: '#5E5E5E', // the unlit part of the wordmark
};
function textAt(x, y, str) {
  let out = '';
  for (const ch of str) {
    if (ch !== ' ') out += `<use href="#${gid(ch)}" x="${x}" y="${y}"/>`;
    x += CW;
  }
  return out;
}
// Readouts that change reuse their words: every run of non-space characters is drawn once as a
// token and referenced wherever it appears (channel lines, pattern cells, the filter value).
const defs = [];
const toks = new Map();
function tok(s) {
  if (!toks.has(s)) { const id = `t${toks.size.toString(36)}`; toks.set(s, id); defs.push(`<g id="${id}">${textAt(0, 0, s)}</g>`); }
  return toks.get(s);
}
function tokens(x, y, str, attrs = '') {
  let out = '';
  for (const m of str.matchAll(/\S+/g)) out += `<use href="#${tok(m[0])}" x="${x + m.index * CW}"${y ? ` y="${y}"` : ''}${attrs}/>`;
  return out;
}
function text(r, c, str) {
  if (r < 0 || r >= ROWS || c < 0 || c + len(str) > COLS) throw new Error(`off screen at ${r},${c}: "${str}"`);
  return textAt(c * CW, r * LH, str);
}
const ink = (cls, inner) => (inner ? `<g class="${cls}">${inner}</g>` : '');
// Coloured segments along a row; returns [svg, next column].
function seg(r, c, parts) {
  let out = '';
  for (const [str, cls] of parts) { out += cls ? ink(cls, text(r, c, str)) : ''; c += len(str); }
  return [out, c];
}
const cells = (cls, r, c, w, h = 1) => `<rect class="${cls}" x="${c * CW}" y="${r * LH}" width="${w * CW}" height="${h * LH}"/>`;

const css = [];
const layers = [];
let uid = 0;
const nid = (p) => `${p}${(uid++).toString(36)}`;
const pct = (t) => `${+((100 * t) / T).toFixed(3)}%`;
const kt = (f) => +(f / NF).toFixed(5);

// SMIL. In --freeze mode nothing animates and every base value is the frozen frame's.
const at0 = (vals) => vals[F0 % vals.length];
function smilLinear(attr, vals) { // vals: one per frame (or per k frames), linear in between
  if (FREEZE !== null) return '';
  return `<animate attributeName="${attr}" dur="${T}s" repeatCount="indefinite" values="${[...vals, vals[0]].join(';')}"/>`;
}
function smilSteps(attr, vals) { // vals: one per frame, held (only changes are written)
  if (FREEZE !== null) return '';
  const k = [], v = [];
  vals.forEach((x, f) => { if (f === 0 || x !== vals[f - 1]) { k.push(kt(f)); v.push(x); } });
  if (v.length === 1) return '';
  return `<animate attributeName="${attr}" dur="${T}s" repeatCount="indefinite" calcMode="discrete" keyTimes="${k.join(';')}" values="${v.join(';')}"/>`;
}
// A text field that rewrites itself: every distinct string once in a strip, and the strip
// stepped behind a one-row window. The still twin shows the frame-0 text.
function ticker(r, c, frames, cls) {
  const w = Math.max(...frames.map(len));
  const uniq = [...new Set(frames)];
  const id = nid('s');
  defs.push(`<g id="${id}">${uniq.map((s, i) => tokens(0, i * LH, s)).join('')}</g>`);
  const ys = frames.map((s) => -uniq.indexOf(s) * LH);
  const live = `<svg x="${c * CW}" y="${r * LH}" width="${w * CW}" height="${LH}"><use href="#${id}" y="${at0(ys)}">${smilSteps('y', ys)}</use></svg>`;
  return ink(cls, `<g class="mo">${live}</g><g class="st">${tokens(c * CW, r * LH, frames[0])}</g>`);
}
// A field that steps through a fixed list on a fixed period: a CSS strip, no SMIL.
function counter(r, c, list, period, cls) {
  const id = nid('k');
  const w = Math.max(...list.map(len));
  css.push(`.${id}{animation:${id} ${period}s steps(${list.length}) infinite}@keyframes ${id}{to{transform:translateY(${-list.length * LH}px)}}`);
  return ink(cls, `<svg x="${c * CW}" y="${r * LH}" width="${w * CW}" height="${LH}"><g class="${id}">${list.map((s, i) => textAt(0, i * LH, s)).join('')}</g></svg>`);
}
// Visible only during the given [from, to) seconds of the loop (hard cuts, like the video).
function vis(intervals) {
  const on = (t) => intervals.some(([a, b]) => t >= a && t < b);
  const name = nid('v');
  const pts = new Map([[0, on(0) ? 1 : 0]]);
  for (const [a, b] of intervals) { if (a > 0) pts.set(a, 1); if (b < T) pts.set(b, on(b) ? 1 : 0); }
  let kf = '';
  for (const [t, v] of [...pts].sort((p, q) => p[0] - q[0])) kf += `${pct(t)}{opacity:${v}}`;
  css.push(`@keyframes ${name}{${kf}100%{opacity:${on(0) ? 1 : 0}}}.${name}{opacity:${on(0) ? 1 : 0};animation:${name} ${T}s step-end infinite}`);
  return name;
}

